-- E0.9 lab (vehicle customization): attach the vehicle-kit test parts to a car.
-- Generated by scripts/vehicle-kit/build-pack.ps1 from scripts/vehicle-kit/lua/e09_server.lua.
-- Visual only (decision D5): props with physics 'none' and no collision, on the
-- vehicle's own slots, so the car keeps its stock wheels, tyres and handling.
-- Every command is restricted (server ACL command.vkit.*) and touches only the
-- props it created; the only vehicle it ever spawns is its own disposable test car.
local ASSETS = 'asset:@@RESOURCE@@/'
local RIMS = @@RIMS@@
local WINGS = @@WINGS@@
local WHEELS = { 'wheel_front_left', 'wheel_front_right', 'wheel_back_left', 'wheel_back_right' }
local TEST_CAR = 'Vehicle.v_standard2_archer_hella_player'
-- First guess for the Archer Hella trunk lid in the vehicle root frame (X right,
-- Y forward, Z up, metres). Tune it live with vkit.move, then write it back here.
local WING_OFFSET = { x = 0.0, y = -1.9, z = 1.05 }
local labs = {}   -- [player] = { car = id or nil, props = { { id, model, vehicle, bone } } }

local function lab(player)
    labs[player] = labs[player] or { props = {} }
    return labs[player]
end

local function reply(player, raw, ok, text)
    print('[vkit] ' .. text)
    if player and player > 0 then TriggerClientEvent('open77:command:result', player, raw or '', ok == true, text) end
    return ok
end

-- "2", "rim_vk1_chrome" or "asset:<resource>/rim_vk1_chrome" -> model id from the list.
local function pick(list, wanted)
    if wanted == nil then return list[1] end
    local index = tonumber(wanted)
    if index then return list[index] end
    wanted = wanted:gsub('^asset:[^/]+/', '')
    for _, id in ipairs(list) do if id == wanted then return id end end
    return nil
end

local function number(text, fallback)
    local n = tonumber(text)
    if n == nil then return fallback end
    return n
end

-- Explicit id, else the car the player sits in, else the lab car, else a new lab car.
local function vehicleFor(player, explicit)
    local state = lab(player)
    if explicit then
        local id = tonumber(explicit)
        if id and Open77.vehicles.get(id) then return id end
        return nil, 'no vehicle ' .. tostring(explicit)
    end
    local seat = Open77.vehicles.getPlayerSeat(player)
    if seat and seat.vehicleId and Open77.vehicles.get(seat.vehicleId) then return seat.vehicleId end
    if state.car and Open77.vehicles.get(state.car) then return state.car end
    local at = Open77.players.position(player)   -- { x, y, z, bucket, yaw? }; needs no permission
    if not at then return nil, 'player_not_ready' end
    local heading = at.yaw or 0
    local r = math.rad(heading)
    -- Yaw 0 faces +Y and turns counter-clockwise: forward is (-sin, cos). The car is
    -- placed 6 m ahead, side-on, so its left wheels face the player.
    local position = { x = at.x - math.sin(r) * 6, y = at.y + math.cos(r) * 6, z = at.z + 0.25 }
    local id, why = Open77.vehicles.create({ record = TEST_CAR, position = position, yaw = heading + 90, bucket = at.bucket })
    if not id then return nil, 'vehicles.create: ' .. tostring(why) end
    state.car = id
    return id
end

local function attach(player, vehicle, model, bone, offset, rotation)
    local car = Open77.vehicles.get(vehicle)
    if not car then return nil, 'vehicle gone' end
    local id, why = Open77.props.create({
        model = ASSETS .. model, position = { x = car.x, y = car.y, z = car.z + 0.5 }, bucket = car.bucket,
        physics = 'none', collision = false, streamingRadius = 150,
    })
    if not id then return nil, 'props.create ' .. model .. ': ' .. tostring(why) end
    local ok, reason = Open77.props.attach(id, {
        parentType = 'vehicle', parentId = vehicle, bone = bone,
        offset = offset or { x = 0, y = 0, z = 0 }, rotation = rotation or { x = 0, y = 0, z = 0 },
    })
    if not ok then
        Open77.props.remove(id)
        return nil, 'props.attach ' .. bone .. ': ' .. tostring(reason)
    end
    table.insert(lab(player).props, { id = id, model = model, vehicle = vehicle, bone = bone })
    return id
end

-- /vkit.rim [model|index] [slot|all] [vehicleId] [mirror]
--   all = the four wheel_* slots. mirror turns the right-hand rims by 180 degrees
--   (only needed if the right slots turn out NOT to be mirrored frames).
RegisterCommand('vkit.rim', function(player, args, raw)
    if not player or player <= 0 then return print('vkit.rim needs a connected player') end
    local model = pick(RIMS, args[1])
    if not model then return reply(player, raw, false, 'unknown rim; models: ' .. table.concat(RIMS, ', ')) end
    local slot = args[2] or 'all'
    local mirror = args[#args] == 'mirror'
    local explicit = args[3] ~= 'mirror' and args[3] or nil
    local vehicle, why = vehicleFor(player, explicit)
    if not vehicle then return reply(player, raw, false, why) end
    local slots = slot == 'all' and WHEELS or { slot }
    local made, ids = {}, {}
    for _, bone in ipairs(slots) do
        local rotation = (mirror and bone:find('_right$')) and { x = 0, y = 0, z = 180 } or nil
        local id, err = attach(player, vehicle, model, bone, nil, rotation)
        if not id then return reply(player, raw, false, err .. ' (' .. #made .. ' attached before)') end
        made[#made + 1] = bone .. '=' .. tostring(id)
        ids[#ids + 1] = id
    end
    TriggerClientEvent('@@RESOURCE@@:inspect', player, vehicle, ids)
    return reply(player, raw, true, ('%s on vehicle %s: %s'):format(model, tostring(vehicle), table.concat(made, ' ')))
end, true)

-- /vkit.wing [model|index] [vehicleId]   root binding at WING_OFFSET
RegisterCommand('vkit.wing', function(player, args, raw)
    if not player or player <= 0 then return print('vkit.wing needs a connected player') end
    local model = pick(WINGS, args[1])
    if not model then return reply(player, raw, false, 'unknown wing; models: ' .. table.concat(WINGS, ', ')) end
    local vehicle, why = vehicleFor(player, args[2])
    if not vehicle then return reply(player, raw, false, why) end
    local id, err = attach(player, vehicle, model, '', WING_OFFSET, nil)
    if not id then return reply(player, raw, false, err) end
    TriggerClientEvent('@@RESOURCE@@:inspect', player, vehicle, { id })
    return reply(player, raw, true, ('%s on vehicle %s root: prop %s'):format(model, tostring(vehicle), tostring(id)))
end, true)

-- /vkit.move <propId> <ox> <oy> <oz> [rx ry rz]   slot-local metres / degrees
RegisterCommand('vkit.move', function(player, args, raw)
    if not player or player <= 0 then return end
    -- props.create returns ids of a different type than tonumber(text) (measured in
    -- E0.9), so both sides are compared as strings and the stored id is the one used.
    local id
    for _, entry in ipairs(lab(player).props) do
        if tostring(entry.id) == tostring(args[1]) then id = entry.id end
    end
    if id == nil then return reply(player, raw, false, 'not one of your vkit props: ' .. tostring(args[1])) end
    local offset = { x = number(args[2], 0), y = number(args[3], 0), z = number(args[4], 0) }
    local rotation = args[5] and { x = number(args[5], 0), y = number(args[6], 0), z = number(args[7], 0) } or nil
    local ok, why = Open77.props.setAttachmentTransform(id, offset, rotation)
    return reply(player, raw, ok ~= nil and ok ~= false, ok and ('prop %s offset %.3f %.3f %.3f'):format(tostring(id), offset.x, offset.y, offset.z) or tostring(why))
end, true)

-- /vkit.list   the player's props with their live binding
RegisterCommand('vkit.list', function(player, args, raw)
    if not player or player <= 0 then return end
    local lines = {}
    for _, entry in ipairs(lab(player).props) do
        local binding = Open77.props.getAttachment(entry.id)
        lines[#lines + 1] = ('%s %s %s/%s %s'):format(tostring(entry.id), entry.model, tostring(entry.vehicle), entry.bone,
            binding and json.encode({ offset = binding.offset, rotation = binding.rotation }) or 'DETACHED')
    end
    return reply(player, raw, true, #lines == 0 and 'no vkit props' or table.concat(lines, ' | '))
end, true)

-- /vkit.clear   removes the player's props and the lab car (never a car it did not create)
RegisterCommand('vkit.clear', function(player, args, raw)
    if not player or player <= 0 then return end
    local state = lab(player)
    for _, entry in ipairs(state.props) do Open77.props.remove(entry.id) end
    local count = #state.props
    if state.car and Open77.vehicles.get(state.car) then Open77.vehicles.remove(state.car) end
    labs[player] = nil
    return reply(player, raw, true, ('removed %d props%s'):format(count, state.car and ' and the lab car' or ''))
end, true)

AddEventHandler('playerDropped', function()
    local player = tonumber(source)
    local state = player and labs[player]
    if not state then return end
    for _, entry in ipairs(state.props) do Open77.props.remove(entry.id) end
    if state.car and Open77.vehicles.get(state.car) then Open77.vehicles.remove(state.car) end
    labs[player] = nil
end)
